import { isUndefined } from 'lodash-es';
import React from 'react';

import { HoneycombDownloadDataButton } from './buttons/HoneycombDownloadDataButton.js';
import { ChartToolbarRenderer } from '../../../core/components/toolbar/ChartToolbarRenderer.js';
import { A11yToolbarTabIndex } from '../../../core/types/toolbar.js';
import { useHoneycombToolbarConfig } from '../../hooks/use-honeycomb-toolbar-config.js';
import { useHoneycombOverlayMouseInBoundsState } from '../../store/selectors.js';
import { useSetStateTooltip } from '../../store/store.js';

export const HoneycombToolbar = () => {
  const initialA11yToolbarTabIndexContext: A11yToolbarTabIndex[] = [
    { download: 0 },
  ];

  const mouseInBounds = useHoneycombOverlayMouseInBoundsState();
  const setTooltipState = useSetStateTooltip();

  const toolbarConfig = useHoneycombToolbarConfig();

  const isDownloadDataEnabled = toolbarConfig?.downloadData?.enabled ?? false;
  const defaultToolbarPlacement = 'top-right';

  const handleMouseEnter = () => {
    setTooltipState({
      enabled: false,
      pinned: false,
    });
  };

  const handleMouseLeave = () => {
    setTooltipState({
      enabled: true,
    });
  };

  return !isUndefined(toolbarConfig) ? (
    <ChartToolbarRenderer
      visible={mouseInBounds && isDownloadDataEnabled}
      collapsed={toolbarConfig.collapsed}
      draggable={toolbarConfig.draggable}
      placement={toolbarConfig.placement || defaultToolbarPlacement}
      initialA11yState={initialA11yToolbarTabIndexContext}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      <HoneycombDownloadDataButton />
    </ChartToolbarRenderer>
  ) : null;
};

HoneycombToolbar['displayName'] = 'HoneycombToolbar';
